import express from 'express';
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const __filename = fileURLToPath(import.meta.url);
const __dirname = path.dirname(__filename);

/**
 * Creates the App Update router for client companions (Android APK, etc.)
 */
export function createAppUpdateRouter({ runtimeEnv = process.env } = {}) {
  const router = express.Router();

  function getDownloadablesInfo() {
    // Check multiple candidate locations for metadata generated by sync script
    const candidateMetaPaths = [
      path.resolve(__dirname, '../../../../apps/frontend/src/generated/downloadMeta.json'),
      path.resolve(__dirname, '../generated/downloadMeta.json'),
      path.resolve(__dirname, '../../public/downloadMeta.json'),
    ];

    let meta = null;
    for (const p of candidateMetaPaths) {
      if (fs.existsSync(p)) {
        try {
          meta = JSON.parse(fs.readFileSync(p, 'utf8'));
          break;
        } catch {}
      }
    }

    const latestAndroidVersionName = runtimeEnv.LATEST_ANDROID_VERSION_NAME || meta?.android?.version || '0.1.1';
    const latestAndroidVersionCode = parseInt(runtimeEnv.LATEST_ANDROID_VERSION_CODE || meta?.android?.versionCode || '2', 10);
    const androidFileSizeBytes = meta?.android?.sizeBytes || 8378634;
    const androidDownloadUrl = runtimeEnv.ANDROID_DOWNLOAD_URL || '/api/v1/app-update/download';

    const latestExtensionVersion = runtimeEnv.LATEST_EXTENSION_VERSION || meta?.extension?.version || '0.3.0';
    const extensionFileSizeBytes = meta?.extension?.sizeBytes || 264153;

    const androidData = {
      platform: 'android',
      version: latestAndroidVersionName,
      versionName: `v${latestAndroidVersionName}`,
      versionCode: latestAndroidVersionCode,
      latestVersionName: latestAndroidVersionName,
      latestVersionCode: latestAndroidVersionCode,
      downloadUrl: androidDownloadUrl,
      directApkUrl: meta?.android?.downloadUrl || '/balakavach-companion.apk',
      fileName: meta?.android?.fileName || 'balakavach-companion.apk',
      sizeBytes: androidFileSizeBytes,
      sizeFormatted: meta?.android?.sizeFormatted || '8.0 MB',
      releaseNotes: meta?.android?.releaseNotes || 'Real-time screen-time tracking, app open counts, bedtime schedule enforcement, and zero-battery VPN-free architecture.',
      features: meta?.android?.features || [
        'Background Screen Time Measurement',
        'Daily Usage & App Launch Limits',
        'Quiet Bedtime Hours Enforcement',
        'Zero VPN Battery-Friendly Engine',
      ],
      publishedAt: meta?.android?.updatedAt || meta?.updatedAt || new Date().toISOString(),
      mandatory: false,
    };

    const extensionData = {
      platform: 'extension',
      version: latestExtensionVersion,
      versionName: `v${latestExtensionVersion}`,
      latestVersionName: latestExtensionVersion,
      downloadUrl: '/api/v1/app-update/download?target=extension',
      directZipUrl: meta?.extension?.downloadUrl || '/balakavach-chrome-extension.zip',
      fileName: meta?.extension?.fileName || 'balakavach-chrome-extension.zip',
      sizeBytes: extensionFileSizeBytes,
      sizeFormatted: meta?.extension?.sizeFormatted || '258 KB',
      releaseNotes: meta?.extension?.releaseNotes || 'Automatic 18+ adult content removal, spontaneous tab purge on connection, and live Chrome browsing history tracking.',
      features: meta?.extension?.features || [
        'Strict 18+ Adult Content Filter',
        'Spontaneous Open Tab Purge on Connect',
        'Live Chrome Browsing History Stream',
        'Parent Dashboard Activity Stream',
      ],
      publishedAt: meta?.extension?.updatedAt || meta?.updatedAt || new Date().toISOString(),
      mandatory: false,
    };

    return {
      // Top-level Android compatibility fields
      platform: 'android',
      latestVersionName: latestAndroidVersionName,
      latestVersionCode: latestAndroidVersionCode,
      downloadUrl: androidDownloadUrl,
      directApkUrl: androidData.directApkUrl,
      releaseNotes: androidData.releaseNotes,
      publishedAt: androidData.publishedAt,
      fileSizeBytes: androidFileSizeBytes,
      mandatory: false,
      // Companion bundles
      android: androidData,
      extension: extensionData,
      updatedAt: meta?.updatedAt || new Date().toISOString(),
    };
  }

  router.get('/', (req, res) => {
    const info = getDownloadablesInfo();
    const isExtension = req.query.platform === 'extension' || req.query.platform === 'chrome' || req.query.target === 'extension';
    const currentCode = parseInt(req.query.currentVersionCode, 10);
    const currentName = req.query.currentVersionName;

    let updateAvailable = false;
    if (isExtension) {
      if (currentName && currentName !== info.extension.version) {
        updateAvailable = true;
      }
      return res.status(200).json({
        ok: true,
        data: {
          ...info.extension,
          updateAvailable,
          android: info.android,
          extension: info.extension,
        },
      });
    }

    if (!Number.isNaN(currentCode) && currentCode < info.latestVersionCode) {
      updateAvailable = true;
    } else if (currentName && currentName !== info.latestVersionName) {
      updateAvailable = true;
    }

    res.status(200).json({
      ok: true,
      data: {
        ...info,
        updateAvailable,
      },
    });
  });

  function serveExtensionDownload(req, res) {
    const candidateZipPaths = [
      path.resolve(__dirname, '../../../../apps/frontend/public/balakavach-chrome-extension.zip'),
      path.resolve(__dirname, '../../../frontend/public/balakavach-chrome-extension.zip'),
      path.resolve(__dirname, '../../public/balakavach-chrome-extension.zip'),
    ];

    for (const p of candidateZipPaths) {
      if (fs.existsSync(p)) {
        res.setHeader('Content-Type', 'application/zip');
        return res.download(p, 'balakavach-chrome-extension.zip');
      }
    }

    const fallbackUrl = runtimeEnv.CHROME_EXTENSION_EXTERNAL_URL ||
      'https://bala-kavach-fe.vercel.app/balakavach-chrome-extension.zip';
    return res.redirect(302, fallbackUrl);
  }

  function serveApkDownload(req, res) {
    const candidateApkPaths = [
      path.resolve(__dirname, '../../../../apps/frontend/public/balakavach-companion.apk'),
      path.resolve(__dirname, '../../../frontend/public/balakavach-companion.apk'),
      path.resolve(__dirname, '../../public/balakavach-companion.apk'),
    ];

    for (const p of candidateApkPaths) {
      if (fs.existsSync(p)) {
        res.setHeader('Content-Type', 'application/vnd.android.package-archive');
        return res.download(p, 'balakavach-companion.apk');
      }
    }

    const fallbackUrl = runtimeEnv.ANDROID_APK_EXTERNAL_URL ||
      'https://bala-kavach-fe.vercel.app/balakavach-companion.apk';
    return res.redirect(302, fallbackUrl);
  }

  router.get('/download/extension', serveExtensionDownload);
  router.get('/download/apk', serveApkDownload);

  router.get('/download', (req, res) => {
    const isExtension = req.query.target === 'extension' || req.query.platform === 'extension' || req.query.platform === 'chrome';
    if (isExtension) {
      return serveExtensionDownload(req, res);
    }
    return serveApkDownload(req, res);
  });

  return router;
}

export default createAppUpdateRouter;
